use semio_framework_test_fixtures::fixture_text;
#[path="../../../../♻️retirement/🧪️tests/⏱️work/🦀️.rs"]mod close_work_policy;
use crate::retained_clone::retained_clone_grant_admits;
use super::*;
use crate::{DslValue,Number,ValueRefusalKind,list::persistent::PersistentList,retained_clone::RetainedCloneSource,retirement::{RetireOwned,controlled::ControlledRetirement},shared_issuance::SealedShared};
#[derive(crate::RetireOwned,crate::NativeReceive)]#[value(crate="crate",native_owned="crate")]
struct Row{label:SealedShared<String>,rank:i64}
impl Clone for Row{fn clone(&self)->Self{panic!("persistent native receiving must never clone an owned typed row")}}


use crate::source_fixture::{Wallet,receive};
fn observe<T>(run:impl FnOnce()->T)->(T,(usize,usize)){crate::observe_retirement_allocations(run)}
fn fixture()->serde_json::Value{serde_json::from_str(fixture_text!("../../📋️list/🧪️tests/🧫️fixtures/📐️.json")).unwrap()}
fn account(p:RetainedCloneProgress,g:RetainedCloneGrant,h:(usize,usize),total:&mut(usize,usize)){assert!(p.fits(g));assert_eq!(h,(p.retained_capacity_bytes,p.released_bytes));total.0+=h.0;total.1+=h.1;}
fn denied(g:RetainedCloneGrant,d:RetirementDemand)->impl Iterator<Item=RetainedCloneGrant>{[(true,RetainedCloneGrant{maximum_items:0,..g}),(d.copy_bytes>0,RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.saturating_sub(1),..g}),(d.capacity_bytes>0,RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes.saturating_sub(1),..g}),(d.release_bytes>0,RetainedCloneGrant{maximum_release_bytes:d.release_bytes.saturating_sub(1),..g}),(d.depth>0,RetainedCloneGrant{maximum_depth:d.depth.saturating_sub(1),..g})].into_iter().filter_map(|(active,g)|active.then_some(g))}
fn input(count:usize,prefix:&str,stride:i64,repeat:usize,bad:Option<usize>)->DslValue{DslValue::Array((0..count).map(|i|DslValue::Object(vec![("label".into(),DslValue::String(if i==0{prefix.repeat(repeat)}else{format!("{prefix}{i}")})),("rank".into(),if bad==Some(i){DslValue::String("refused".into())}else{DslValue::Number(Number::Int(i as i64*stride))})])).collect())}
fn source<I:RetireOwned+Sync>(value:I,bank:&mut Wallet,total:&mut(usize,usize))->RetainedCloneSource<I>{let mut wallet=(bank,total);crate::source_fixture::capture(value,&mut wallet,|w|w.0.loan(1,4096),|w|w.0.work_remaining(),|w,p,work,heap,g|{account(p,g,heap,w.1);w.0.post(p,work,g,heap)})}
fn make_original(count:usize,prefix:&str,stride:i64,repeat:usize,bad:Option<usize>,bank:&mut Wallet,total:&mut(usize,usize))->RetainedCloneSource<DslValue>{let(value,h)=observe(||input(count,prefix,stride,repeat,bad));total.0+=h.0;total.1+=h.1;source(value,bank,total)}
fn post<E:std::fmt::Debug>(bank:&mut Wallet,turn:crate::RetainedWorkOutcome<RetainedCloneStep,E>,g:RetainedCloneGrant,heap:(usize,usize),total:&mut(usize,usize),receipt:impl FnOnce(&E)->RetainedCloneProgress)->Result<RetainedCloneStep,E>{let p=turn.result.as_ref().map(|s|s.progress()).unwrap_or_else(receipt);account(p,g,heap,total);bank.post(p,turn.work,g,heap);turn.result}
fn close<T:RetireOwned>(value:T,bank:&mut Wallet,total:&mut(usize,usize)){let mut retirement_actual=None;let mut retirement_work=0;let(mut owner,h)=observe(||ControlledRetirement::new(value).unwrap_or_else(|_|panic!("persistent fixture retirement")));assert_eq!(h,(0,0));let mut work=close_work_policy::Work::new();while !owner.terminal_is_empty()||retirement_actual.is_some(){let d=owner.next_demand(4096).unwrap();assert!(d.copy_bytes<=4096,"selected close quote exceeds its authored body");let g=bank.loan(1,4096);let(result,h)=observe(||{let turn=crate::source_fixture::close_step(&mut retirement_actual,g,bank.work_remaining(),owner.next_demand(4096),owner.next_computational_work(4096),|g,a|{let result=owner.step(g,a);crate::RetainedWorkOutcome{result,work:owner.last_turn_work()}});retirement_work=turn.work;turn.result});let actual=retirement_work;let s=post(bank,crate::RetainedWorkOutcome{result,work:actual},g,h,total,|e|e.retained_progress()).unwrap();work.observe(s.progress()==Default::default()&&!owner.terminal_is_empty()&&owner.next_demand(4096).unwrap()==d);}assert_eq!(observe(||drop(owner)).1,(0,0));}
fn close_receiver<I:NativeListSource+?Sized>(receiver:&mut NativePersistentListReceiver<I,Row>,rows:usize,bank:&mut Wallet,total:&mut(usize,usize))where Row:NativeReceive<I::Row>{let g=bank.loan(1,4096);let q=receiver.begin_close_work_demand().unwrap();assert!(q<=bank.work_remaining());let(turn,h)=observe(||receiver.begin_close_step(g,q));post(bank,turn,g,h,total,|e|panic!("unexpected close-intent refusal: {e:?}")).unwrap();let mut actual=None;let mut work=close_work_policy::Work::for_rows(rows);while !receiver.terminal_is_empty()||actual.is_some(){let d=crate::source_fixture::close_demands(&actual,receiver.close_demands(4096)).unwrap();assert!(d.copy_bytes<=4096,"selected close quote exceeds its authored body");let g=bank.loan(1,4096);for denied in denied(g,d){let(turn,h)=observe(||crate::source_fixture::close_step(&mut actual,denied,bank.work_remaining(),receiver.close_demands(4096),receiver.close_work_demand(4096),|g,a|receiver.close_step(g,a)));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(h,(0,0));}let(turn,h)=observe(||crate::source_fixture::close_step(&mut actual,g,bank.work_remaining(),receiver.close_demands(4096),receiver.close_work_demand(4096),|g,a|receiver.close_step(g,a)));let s=post(bank,turn,g,h,total,|e|e.retained_progress()).unwrap();work.observe(s.progress()==Default::default()&&!receiver.terminal_is_empty()&&crate::source_fixture::close_demands(&actual,receiver.close_demands(4096)).unwrap()==d);}}
fn take<I:NativeListSource+?Sized>(receiver:&mut NativePersistentListReceiver<I,Row>,g:RetainedCloneGrant,bank:&mut Wallet,total:&mut(usize,usize))->PersistentList<Row>where Row:NativeReceive<I::Row>{let(turn,h)=observe(||receiver.take(g));let p=turn.result.as_ref().unwrap().as_ref().map(|(_,p)|*p).unwrap_or_default();account(p,g,h,total);bank.post(p,turn.work,g,h);turn.result.unwrap().unwrap().0}
#[test]fn native_persistent_list_receives_original_rows_and_preserves_all_cancelled_custody(){
 let f=fixture();let prefix=f["prefix"].as_str().unwrap();let stride=f["stride"].as_i64().unwrap();let repeat=f["firstRepeat"].as_u64().unwrap()as usize;
 for count in f["cases"].as_array().unwrap(){let count=count.as_u64().unwrap()as usize;for cut in std::iter::once(None).chain(f["cuts"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap()as usize))){let mut bank=Wallet::from_profile(&f["stock"]);let mut total=(0,0);let original=make_original(count,prefix,stride,repeat,None,&mut bank,&mut total);let foreign=make_original(count,prefix,stride,repeat,None,&mut bank,&mut total);let pointer=std::ptr::from_ref(original.borrow().get());let expected=serde_json::Value::from(original.borrow().get());let(mut receiver,h)=observe(<PersistentList<Row>as NativeReceive<DslValue>>::receiver);assert_eq!(h,(0,0));let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<30,&mut callback);let mut turns=0;let mut prepared=0;let mut output=None;let mut work=close_work_policy::Work::for_rows(count);
  while !receiver.output_ready()&&cut.is_none_or(|cut|turns<cut){let d=receiver.demands(original.borrow(),512,bank.work_remaining()).unwrap();if turns>0{assert!(receiver.demands(foreign.borrow(),512,bank.work_remaining()).is_err())}let g=bank.loan(1,4096);for denied in denied(g,d){let(turn,h)=observe(||receive(&mut control,denied,bank.work_loan(bank.work_remaining()),|control|{let maximum=control.available_work_units().unwrap();receiver.advance(original.borrow(),control,512,maximum,denied)}));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(receiver.demands(original.borrow(),512,bank.work_remaining()).unwrap(),d);}let(turn,h)=observe(||receive(&mut control,g,bank.work_loan(bank.work_remaining()),|control|{let maximum=control.available_work_units().unwrap();receiver.advance(original.borrow(),control,512,maximum,g)}));let s=post(&mut bank,turn,g,h,&mut total,crate::OriginalReceivingPrimary::retained_progress).unwrap();prepared+=h.0;assert_eq!(control.owned_bytes(),prepared);assert_eq!(std::ptr::from_ref(original.borrow().get()),pointer);turns+=1;work.observe(s.progress()==Default::default()&&!receiver.output_ready()&&receiver.demands(original.borrow(),512,bank.work_remaining()).unwrap()==d);}
  if cut.is_none(){let d=receiver.take_demand().unwrap();let g=bank.loan(1,4096);for denied in denied(g,d){let(turn,h)=observe(||receiver.take(denied));assert_eq!(turn.work,0);assert!(turn.result.unwrap().is_none());assert_eq!(h,(0,0));}let root=take(&mut receiver,g,&mut bank,&mut total);assert_eq!(root.len(),count);let actual:Vec<_>=(0..count).map(|i|{let row=root.get(i).unwrap();serde_json::json!({"label":row.label.as_str(),"rank":row.rank})}).collect();assert_eq!(serde_json::Value::Array(actual),expected);output=Some(root);}
  close_receiver(&mut receiver,count,&mut bank,&mut total);assert_eq!(observe(||drop(receiver)).1,(0,0));close(foreign,&mut bank,&mut total);close(original,&mut bank,&mut total);if let Some(root)=output{for i in 0..count{assert_eq!(root.get(i).unwrap().rank,i as i64*stride);}close(root,&mut bank,&mut total);}assert_eq!(total.0,total.1);
 }}
}
#[test]fn native_persistent_list_later_row_refusal_retains_original_partial_owner(){let f=fixture();for bad in f["invalidRows"].as_array().unwrap(){let mut bank=Wallet::from_profile(&f["stock"]);let mut total=(0,0);let original=make_original(257,"α🙂",2,1,Some(bad.as_u64().unwrap()as usize),&mut bank,&mut total);let before=serde_json::Value::from(original.borrow().get());let mut receiver=<PersistentList<Row>as NativeReceive<DslValue>>::receiver();let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<30,&mut callback);let mut refused=false;let mut work=close_work_policy::Work::for_rows(257);while !receiver.output_ready(){let d=receiver.demands(original.borrow(),512,bank.work_remaining()).unwrap();let g=bank.loan(1,4096);let(turn,h)=observe(||receive(&mut control,g,bank.work_loan(bank.work_remaining()),|control|{let maximum=control.available_work_units().unwrap();receiver.advance(original.borrow(),control,512,maximum,g)}));match post(&mut bank,turn,g,h,&mut total,crate::OriginalReceivingPrimary::retained_progress){Ok(s)=>work.observe(s.progress()==Default::default()&&!receiver.output_ready()&&receiver.demands(original.borrow(),512,bank.work_remaining()).unwrap()==d),Err(error)=>{assert_eq!(error.primary.as_ref().unwrap().kind,ValueRefusalKind::InvalidValue);refused=true;break}}}assert!(refused);assert_eq!(serde_json::Value::from(original.borrow().get()),before);close_receiver(&mut receiver,257,&mut bank,&mut total);assert_eq!(observe(||drop(receiver)).1,(0,0));close(original,&mut bank,&mut total);assert_eq!(total.0,total.1);}}
#[test]fn native_persistent_list_original_callback_refusal_preserves_partial_receiving(){let f=fixture();for allow in[0usize,1,3,8,31,256]{let mut bank=Wallet::from_profile(&f["stock"]);let mut total=(0,0);let original=make_original(17,"α🙂",2,10923,None,&mut bank,&mut total);let before=serde_json::Value::from(original.borrow().get());let mut receiver=<PersistentList<Row>as NativeReceive<DslValue>>::receiver();let calls=std::cell::Cell::new(0);let mut callback=|_|{let n=calls.get();calls.set(n+1);n<allow};let mut control=NativeDecodeControl::new(1<<30,&mut callback);let mut stopped=false;let mut work=close_work_policy::Work::for_rows(17);while !receiver.output_ready(){let d=receiver.demands(original.borrow(),512,bank.work_remaining()).unwrap();let g=bank.loan(1,4096);let(turn,h)=observe(||receive(&mut control,g,bank.work_loan(bank.work_remaining()),|control|{let maximum=control.available_work_units().unwrap();receiver.advance(original.borrow(),control,512,maximum,g)}));match post(&mut bank,turn,g,h,&mut total,crate::OriginalReceivingPrimary::retained_progress){Ok(s)=>work.observe(s.progress()==Default::default()&&!receiver.output_ready()&&receiver.demands(original.borrow(),512,bank.work_remaining()).unwrap()==d),Err(error)=>{assert_eq!(error.primary.as_ref().unwrap().kind,ValueRefusalKind::Canceled);stopped=true;break}}}assert!(stopped);assert_eq!(serde_json::Value::from(original.borrow().get()),before);close_receiver(&mut receiver,17,&mut bank,&mut total);assert_eq!(observe(||drop(receiver)).1,(0,0));close(original,&mut bank,&mut total);assert_eq!(total.0,total.1);}}
#[test]fn native_persistent_list_original_vector_owner_fits_quantum_and_keeps_custody(){type Owner=crate::owned::NativeReceivingOriginal<Vec<DslValue>,PersistentList<Row>>;let f=fixture();let copy=f["interactionQuantum"]["copyBytes"].as_u64().unwrap()as usize;let items=f["interactionQuantum"]["workItems"].as_u64().unwrap()as usize;for cut in std::iter::once(None).chain(f["ownedWrapperCuts"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap()as usize))){let mut bank=Wallet::from_profile(&f["stock"]);let((rows,),seed)=observe(||{let DslValue::Array(rows)=input(17,"α🙂",2,1,None)else{unreachable!()};(rows,)});let mut total=seed;let original=source(rows,&mut bank,&mut total);let pointer=std::ptr::from_ref(original.borrow().get());let(mut owner,h)=observe(||Owner::new(original));assert_eq!(h,(0,0));assert_eq!(std::ptr::from_ref(owner.borrow_input().unwrap().get()),pointer);let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<30,&mut callback);let mut prepared=0;let mut turns=0;let mut output=None;let mut work=close_work_policy::Work::for_rows(17);while !owner.output_ready()&&cut.is_none_or(|cut|turns<cut){let d=owner.demands(copy).unwrap();assert!(d.copy_bytes<=copy,"original vector wrapper exceeds responsive quantum");let g=bank.loan(items,copy);let(turn,h)=observe(||receive(&mut control,g,bank.work_loan(f["interactionQuantum"]["workUnits"].as_u64().unwrap()),|control|owner.advance(control,copy,g)));let s=post(&mut bank,turn,g,h,&mut total,crate::OriginalReceivingPrimary::retained_progress).unwrap();prepared+=h.0;assert_eq!(control.owned_bytes(),prepared);assert_eq!(std::ptr::from_ref(owner.borrow_input().unwrap().get()),pointer);turns+=1;work.observe(s.progress()==Default::default()&&!owner.output_ready()&&owner.demands(copy).unwrap()==d);}if cut.is_none(){let g=bank.loan(items,copy);let(turn,h)=observe(||owner.take(g));let p=turn.result.as_ref().unwrap().as_ref().map(|(_,p)|*p).unwrap_or_default();account(p,g,h,&mut total);bank.post(p,turn.work,g,h);let(root,_)=turn.result.unwrap().unwrap();assert_eq!(root.len(),17);for i in 0..17{assert_eq!(root.get(i).unwrap().rank,i as i64*2);}output=Some(root);}let g=bank.loan(1,4096);let q=owner.begin_close_work_demand().unwrap();assert!(q<=bank.work_remaining());let(turn,h)=observe(||owner.begin_close_step(g,q));post(&mut bank,turn,g,h,&mut total,|e|panic!("unexpected close-intent refusal: {e:?}")).unwrap();let mut actual=None;let mut work=close_work_policy::Work::for_rows(17);while !owner.terminal_is_empty()||actual.is_some(){let d=owner.close_demands(copy).unwrap();assert!(d.copy_bytes<=copy);let g=bank.loan(items,copy);let(turn,h)=observe(||{crate::source_fixture::close_step(&mut actual,g,bank.work_remaining(),owner.close_demands(copy),owner.close_work_demand(copy),|g,a|owner.close_step(g,a))});let s=post(&mut bank,turn,g,h,&mut total,crate::OriginalReceivingPrimary::retained_progress).unwrap();prepared+=h.0;assert_eq!(control.owned_bytes(),prepared);work.observe(s.progress()==Default::default()&&!owner.terminal_is_empty()&&owner.close_demands(copy).unwrap()==d);}assert_eq!(observe(||drop(owner)).1,(0,0));if let Some(root)=output{close(root,&mut bank,&mut total);}assert_eq!(total.0,total.1);}}
